import os
import boto3

def extract_table_structure(file_path: str) -> list[list[list[str]]]:
    """
    Extracts table cells and row structure from a document using Amazon Textract.
    Returns a list of tables, where each table is represented as a list of rows,
    and each row is a list of cell strings.
    """
    client = boto3.client(
        'textract',
        aws_access_key_id=os.environ.get('AWS_ACCESS_KEY_ID'),
        aws_secret_access_key=os.environ.get('AWS_SECRET_ACCESS_KEY'),
        region_name=os.environ.get('AWS_DEFAULT_REGION', 'us-east-1')
    )

    with open(file_path, 'rb') as f:
        document_bytes = f.read()

    response = client.analyze_document(
        Document={'Bytes': document_bytes},
        FeatureTypes=['TABLES']
    )

    blocks_map = {block['Id']: block for block in response['Blocks']}
    extracted_tables = []

    for block in response['Blocks']:
        if block['BlockType'] == 'TABLE':
            cell_data = {}

            for rel in block.get('Relationships', []):
                if rel['Type'] == 'CHILD':
                    for cell_id in rel['Ids']:
                        cell = blocks_map[cell_id]
                        if cell['BlockType'] == 'CELL':
                            row_idx = cell.get('RowIndex', 1)
                            col_idx = cell.get('ColumnIndex', 1)

                            cell_words = []
                            if 'Relationships' in cell:
                                for cell_rel in cell['Relationships']:
                                    if cell_rel['Type'] == 'CHILD':
                                        for word_id in cell_rel['Ids']:
                                            word_block = blocks_map[word_id]
                                            cell_words.append(word_block.get('Text', ''))

                            cell_data.setdefault(row_idx, {})[col_idx] = ' '.join(cell_words).strip()

            if not cell_data:
                continue

            max_row = max(cell_data.keys())
            max_col = max(max(cols.keys()) for cols in cell_data.values())

            table_grid = []
            for r in range(1, max_row + 1):
                row_cells = []
                for c in range(1, max_col + 1):
                    row_cells.append(cell_data.get(r, {}).get(c, ''))
                table_grid.append(row_cells)

            extracted_tables.append(table_grid)

    return extracted_tables
